IEnumerator AnimarBarra(float duracion)
{
    float tiempo = 0;
    while (tiempo < duracion)
    {
        tiempo += Time.deltaTime;
        barraUI.fillAmount = tiempo / duracion;
        yield return null;
    }
    barraUI.fillAmount = 1f;
}

